<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {api,errorText} from '../state'
import Brand from '../components/Brand.vue'
import Icon from '../components/Icon.vue'
const props=defineProps({embedded:Boolean}),emit=defineEmits(['changed'])
const dialog=ref(null),rows=ref([]),draft=reactive({}),busy=ref(''),error=ref(''),messages=reactive({})
const pending=computed(()=>Boolean(busy.value))
async function load(){error.value='';try{rows.value=(await api('/api/admin/crypto-networks')).networks;for(const row of rows.value)draft[row.network]={revision:row.revision,rpc_url:row.rpc_url,api_key:'',confirmations:row.confirmations}}catch(e){error.value=errorText(e)}}
async function open(){await load();dialog.value?.showModal()}
async function save(network){if(pending.value)return;busy.value=network;error.value='';messages[network]='正在验证';try{const saved=await api(`/api/admin/crypto-networks/${network}`,{method:'PUT',body:JSON.stringify(draft[network])});draft[network].revision=saved.config.revision;const checked=await api(`/api/admin/crypto-networks/${network}/check`,{method:'POST',signal:AbortSignal.timeout(60000)});if(!checked.verified)throw new Error(checked.provider_code||'crypto_network_check_failed');draft[network].revision=checked.revision;draft[network].rpc_url=checked.rpc_url;messages[network]=checked.fallback_used?'已切换免费节点并验证':'检查通过';emit('changed')}catch(e){messages[network]='检查失败';error.value=`${network}：${errorText(e)}`}finally{busy.value=''}}
onMounted(()=>{if(!props.embedded)load()})
defineExpose({open})
</script>
<template><component :is="embedded?'dialog':'section'" id="crypto-network-settings" ref="dialog" :class="['nodes-panel',{'nodes-dialog':embedded}]" @cancel.prevent="!pending&&dialog.close()">
  <header class="nodes-heading"><div><h2>Crypto 网络设置</h2><p>已预填公益 RPC，无需填写 API Key 即可先保存检查</p></div><button v-if="embedded" type="button" class="icon-button" aria-label="关闭网络设置" :disabled="pending" @click="dialog.close()"><Icon name="x"/></button></header>
  <p v-if="error" class="nodes-error" role="alert">{{error}}</p>
  <div class="nodes-grid"><article v-for="row in rows" :key="row.network" class="node-card hig-card">
    <header><span class="node-name"><Brand :name="`network-${row.network}`"/>{{row.network}}</span><span class="node-state" :class="{verified:messages[row.network]==='检查通过'||row.checked}">{{messages[row.network]||(row.checked?'检查通过':'待检查')}}</span></header>
    <div class="node-line"><label :for="`rpc-${row.network}`"><span>RPC 地址</span><input :id="`rpc-${row.network}`" v-model.trim="draft[row.network].rpc_url" type="text" required :disabled="pending" spellcheck="false"/></label><label :for="`confirm-${row.network}`"><span>确认数</span><input :id="`confirm-${row.network}`" v-model.number="draft[row.network].confirmations" type="number" min="1" max="10000" :disabled="pending"/></label></div>
    <div class="node-line"><label :for="`key-${row.network}`"><span>API Key（可选）</span><input :id="`key-${row.network}`" v-model="draft[row.network].api_key" type="password" autocomplete="new-password" :placeholder="row.api_key_configured?'已保存，留空保留':'公益节点通常留空'" :disabled="pending"/></label><button type="button" class="button button-secondary node-save" :disabled="pending||!draft[row.network].rpc_url" @click="save(row.network)"><Icon :name="busy===row.network?'loader':'check'" :class="{spin:busy===row.network}" :size="14"/>保存并检查</button></div>
  </article></div>
</component></template>
<style scoped>
.nodes-panel{min-width:0;height:min(650px,calc(100svh - 232px));display:flex;flex-direction:column;gap:12px}.nodes-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex:none}.nodes-heading h2{font-size:17px;margin:0}.nodes-heading p{font-size:12px;color:var(--muted);margin:5px 0 0}.nodes-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr));gap:10px;flex:1;min-height:0}.node-card{padding:12px;min-width:0;display:flex;flex-direction:column;justify-content:center;gap:9px}.node-card header,.node-name{display:flex;align-items:center;gap:7px}.node-card header{justify-content:space-between}.node-name{font-weight:650;font-size:12px}.node-name :deep(img){width:20px;height:20px}.node-state{font-size:10px;color:var(--muted)}.node-state.verified{color:#187953}.node-line{display:grid;grid-template-columns:minmax(0,1fr) 106px;gap:10px;align-items:end}.node-line label{display:flex;flex-direction:column;gap:5px;min-width:0;margin:0;font-size:11px;color:var(--muted)}.node-line input{min-width:0;box-sizing:border-box;width:100%;height:33px;min-height:33px;padding:5px 8px;font-size:11px;border:1px solid var(--line);border-radius:7px;background:var(--bg);color:var(--text)}.node-save{height:33px;min-height:33px;padding:4px 7px;white-space:nowrap;font-size:11px;display:inline-flex;align-items:center;justify-content:center;gap:5px}.nodes-error{font-size:12px;color:#bb3434;margin:0;flex:none}.nodes-dialog{position:fixed;inset:74px 0 0 var(--sidebar-w);margin:auto;width:min(1500px,calc(100vw - var(--sidebar-w) - 26px));height:min(640px,calc(100svh - 102px));max-width:none;max-height:calc(100svh - 102px);padding:16px;border:1px solid var(--line);border-radius:18px;background:var(--card);color:var(--text);box-sizing:border-box}.nodes-dialog:not([open]){display:none}.nodes-dialog::backdrop{background:#15131866}@media(max-width:1000px){.nodes-grid{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:none;overflow:auto}.node-card{min-height:172px}.nodes-dialog{inset:74px 12px 12px;margin:auto;width:calc(100vw - 24px)}}@media(max-width:600px){.nodes-grid{grid-template-columns:minmax(0,1fr)}.nodes-panel{height:auto}.nodes-dialog{height:calc(100svh - 100px)}.nodes-heading p{max-width:250px}}
</style>
